def split_blocks(grid):
    """The two blocks on either side of a single full-height column or full-width row of one color: (orientation, first block, second block)."""
    rows, cols = separator_lines(grid)
    H, W = len(grid), len(grid[0])
    if cols:
        j = cols[0]
        return 'v', [r[:j] for r in grid], [r[j + 1:] for r in grid]
    i = rows[0]
    return 'h', grid[:i], grid[i + 1:]

def shared_color_mark(grid, mark=3):
    """The two blocks split by a full separator line, marked where both blocks show the color they share; that shared color elsewhere."""
    _, A, B = split_blocks(grid)
    shared = ({v for r in A for v in r} & {v for r in B for v in r}).pop()
    return [[mark if a == shared and b == shared else shared for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]


def stamp_marker_motif(grid, bg=None, noise=None, anchor=None):
    """Stamp the grid's small multi-color motif centered on every isolated noise dot."""
    from collections import Counter as _C
    bg = bg if bg is not None else background(grid)
    cnt = _C(v for r in grid for v in r)
    cands = [c for c in cnt if c != bg]
    noise = noise if noise is not None else max(cands, key=lambda c: cnt[c])
    ys = [y for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    xs = [x for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    motif = [row[x0:x1 + 1] for row in grid[y0:y1 + 1]]
    H, W = len(motif), len(motif[0])
    ay, ax = anchor if anchor is not None else ((H - 1) // 2, (W - 1) // 2)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for y in range(h):
        for x in range(w):
            if grid[y][x] == noise:
                for dy in range(H):
                    for dx in range(W):
                        yy, xx = y + dy - ay, x + dx - ax
                        if 0 <= yy < h and 0 <= xx < w:
                            out[yy][xx] = motif[dy][dx]
    return out


def comps(grid, color):
    """8-connected components of a color as sets of (y,x)."""
    cells=[(y,x) for y,r in enumerate(grid) for x,v in enumerate(r) if v==color]
    out=[]
    while cells:
        s=[cells.pop()]
        cl=set(s)
        while s:
            y,x=s.pop()
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    p=(y+dy,x+dx)
                    if p in cells:
                        cells.remove(p); cl.add(p); s.append(p)
        out.append(cl)
    return out

def norm_shape(comp):
    """Translation-invariant frozenset shape of a component."""
    y0=min(y for y,x in comp); x0=min(x for y,x in comp)
    return frozenset((y-y0,x-x0) for y,x in comp)

def has_2x2(comp):
    """True if the component contains a filled 2x2 block."""
    s=set(comp)
    return any((y,x) in s and (y,x+1) in s and (y+1,x) in s and (y+1,x+1) in s for y,x in s)

def l_stroke(grid, bg=None):
    """The stroke: largest 2x2-free component; returns (color, cells set)."""
    bg=bg if bg is not None else background(grid)
    cc={}
    for c in set(v for r in grid for v in r)-{bg}:
        cc[c]=comps(grid,c)
    best=max((comp for cl in cc.values() for comp in cl if not has_2x2(comp)), key=len)
    return grid[next(iter(best))[0]][next(iter(best))[1]], set(best)

def concave_twin_recolor(grid, bg=None):
    """Recolor to the L-stroke color the shape-twin of the component nested in the L's concave corner."""
    bg=bg if bg is not None else background(grid)
    dst,stroke=l_stroke(grid,bg)
    ys=[y for y,x in stroke]; xs=[x for y,x in stroke]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    cc={c:comps(grid,c) for c in set(v for r in grid for v in r)-{bg}}
    inside=[comp for c,cl in cc.items() if c!=dst for comp in cl
            if all(y0<=y<=y1 and x0<=x<=x1 for y,x in comp) and not (comp & stroke)]
    assert len(inside)==1
    inner=norm_shape(inside[0])
    groups={}
    for c,cl in cc.items():
        if c==dst: continue
        for comp in cl: groups.setdefault(norm_shape(comp),[]).append(comp)
    twins=[m for m in groups[inner] if m!=inside[0]]
    assert len(twins)==1
    out=[row[:] for row in grid]
    for y,x in twins[0]: out[y][x]=dst
    return out

from collections import Counter, deque

def background_color(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def same_color_components(grid, c):
    """4-connected components of a single color as lists of (row, col)."""
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == c and (i, j) not in seen:
